export type ChallengeLevel = 'debutant' | 'intermediaire' | 'avance' | 'expert' | 'professionnel';
export type ChallengeType = 'decision' | 'calculation' | 'reads' | 'gto' | 'icm';

export interface VillainProfile {
  name: string;
  emoji: string;
  style: string;
  vpip: number;
  pfr: number;
  description: string;
  tendency: string;
}

export interface ChallengeOption {
  label: string;
  isCorrect: boolean;
  explanation: string;
}

export interface Challenge {
  id: string;
  level: ChallengeLevel;
  difficulty: 1 | 2 | 3;
  type: ChallengeType;
  title: string;
  hint?: string;
  villain: VillainProfile;
  context: {
    gameType: 'cash' | 'tournament';
    blinds: string;
    position: string;
    effectiveStack: string;
    street: 'preflop' | 'flop' | 'turn' | 'river';
    pot: string;
    heroHand: [string, string];
    board: string[];
    action: string;
  };
  question: string;
  options: ChallengeOption[];
  lesson: string;
  mathNote?: string;
  xp: number;
}

