    context: { gameType: 'cash', blinds: '1/2', position: 'CO vs BB', effectiveStack: '80BB', street: 'river', pot: '45', heroHand: ['A♥', 'K♦'], board: ['A♦', '9♣', '5♠', '2♥', '7♦'], action: 'BB (fish aggro) mise soudainement 80$ (1.8x pot) sur la river après avoir check-callé flop et turn.' },
    question: 'Tu as TPTK. Villain fish aggro fait soudain un overbet river après deux check-calls passifs. Que signifie ce bet et que fais-tu ?',
