    context: { gameType: 'cash', blinds: '1/2', position: 'BTN vs BB', effectiveStack: '100BB', street: 'flop', pot: '12', heroHand: ['A♠', 'Q♦'], board: ['A♦', '7♣', '2♠'], action: 'BB check-raise all-in (si tu c-bet).' },
