    question: 'Tu as QQ sur un board A-7-2. Un LAG très agressif c-bet. Sa tendance : "barrel toutes les cartes de turn et river". Quelle est la ligne exploitative optimale ?',
    options: [
      { label: 'Fold — l\'As sur le board est mauvais pour QQ', isCorrect: false, explanation: 'Contre un LAG qui barrel toutes les cartes, folder QQ (underpair) est peut-être trop tight. Analyse son range de barrel vs son range de valeur.' },
      { label: 'Call flop, call turn, évaluer river — exploite son barrel fréquent', isCorrect: true, explanation: 'Exact ! Si le LAG barrel toutes les cartes (bluff aussi), ta QQ devient un excellent bluff-catcher sur plusieurs streets. Call flop, call turn (il barrel encore), et évalue la river. Tu extrais de la valeur de ses bluffs.' },
      { label: 'Check-raise flop pour tester sa main', isCorrect: false, explanation: 'Check-raise avec QQ vs un LAG peut provoquer un 3-bet de sa part. Si tu n\'as pas de plan vs son 3-bet, call est plus sûr et extrait mieux vs ses bluffs.' },
      { label: 'Call flop et fold turn — le barrel signifie souvent une main forte', isCorrect: false, explanation: 'Il barrel TOUTES les cartes — pas seulement avec des bonnes mains. Fold turn perd la valeur de bluff-catching que tu as.' },
    ],
