    context: { gameType: 'tournament', blinds: '20000/40000', position: 'SB vs BB', effectiveStack: '40BB', street: 'preflop', pot: '60000', heroHand: ['Q♣', 'J♣'], board: [], action: 'Tu es SB. Action à toi.' },
    question: 'Final table 6-handed. Payouts : 1er=40%, 2e=25%, 3e=15%, 4e=10%, 5e=6%, 6e=4%. Stack equal. Dois-tu open push QJ♣ de SB ?',
    options: [
      { label: 'Push — QJ♣ est assez fort pour un open push', isCorrect: false, explanation: 'En chip EV, push QJ est probablement +EV. Mais en ICM final table avec payout top-lourd, les décisions changent. Le bubble factor modifie le threshold de push/fold.' },
      { label: 'Fold — ICM pression final table rend QJ un fold même en SB', isCorrect: false, explanation: 'Fold QJ en SB à 40BB est trop tight. QJ♣ a de l\'équité et le push est généralement profitable même en ICM final table avec payout modéré.' },
      { label: 'Push — QJ♣ est dans le range profitable même avec l\'ICM modéré de ce payout', isCorrect: true, explanation: 'Correct ! Avec un payout 40/25/15/10/6/4% (pas trop top-lourd), le push QJ♣ de SB à 40BB est dans le range ICM profitable. Le bubble factor modifié n\'est pas assez grand pour fold une main aussi forte.' },
      { label: 'Limp et évaluer post-flop', isCorrect: false, explanation: 'Limper de SB à 40BB est une erreur. Soit push (pour la fold equity), soit fold. Le limp perd la fold equity sans améliorer l\'équité.' },
    ],
    lesson: 'Le bubble factor ICM est plus fort avec des payouts top-lourds (winner-take-all) et plus faible avec des payouts plats. Avec un payout distribué, QJ♣ reste un push en SB à 40BB.',
    xp: 170,
